-- 2026-11-04 명품관 B클래스 명예 테두리 3종 추가: 진주의 서약 · 흑염의 맹세 · 서릿결의 맹세
--
-- 이 파일은 '상품 데이터 등록'만 합니다. 함수(student_get_expedition_luxury_shop, student_purchase_cosmetic)는
-- 10/10 파일에서 이미 적용된 것을 그대로 쓰므로 다시 만들지 않습니다.
--
-- 판매 조건
--   * 가격: 300 GOLD (기존 3종과 동일)
--   * 판매 기간: 2026-11-04 00:00 ~ 2026-11-10 00:00 (KST) — 종료일은 기존 3종과 동일
--   * 구매 조건: 월드 효과 '명품관 개방 Lv.2'가 켜져 있을 때만 구매 가능
--       - metadata 의 trial_open 을 반드시 false 로 둔다. (체험 개방이 아님)
--       - ※ metadata 를 비워 두면('{}') 구매 함수의 Lv2 검사가 건너뛰어질 수 있으므로 false 를 명시한다.
--   * Lv2 가 꺼져 있으면 상점 목록에도 나오지 않고, 구매 함수도 거절한다.
--
-- 여러 번 실행해도 안전합니다(이미 있으면 갱신만 하고, 구매 이력은 건드리지 않음).
begin;

insert into public.cosmetic_items(item_uid,category,name,description,resource_url,is_active)
values
  ('PRESTIGE_PEARL_2026','prestige_border','진주의 서약','청록 물결과 산호빛 진주가 어우러진 명예 테두리.','data:image/webp;base64,',true),
  ('PRESTIGE_DARKFLAME_2026','prestige_border','흑염의 맹세','잿빛 사슬 위로 보랏빛 불꽃이 타오르는 명예 테두리.','data:image/webp;base64,',true),
  ('PRESTIGE_FROST_2026','prestige_border','서릿결의 맹세','새하얀 서리와 얼음 결정이 피어난 명예 테두리.','data:image/webp;base64,',true)
on conflict(item_uid) do update
set category=excluded.category,name=excluded.name,description=excluded.description,
    resource_url=excluded.resource_url,is_active=true;

insert into public.cosmetic_item_pricings(item_id,value_token,price,condition_type,is_active)
select ci.id,'GOLD',300,'NONE',true
from public.cosmetic_items ci
where ci.item_uid in ('PRESTIGE_PEARL_2026','PRESTIGE_DARKFLAME_2026','PRESTIGE_FROST_2026')
  and not exists (
    select 1 from public.cosmetic_item_pricings cp
    where cp.item_id=ci.id and cp.value_token='GOLD' and cp.price=300
  );

insert into public.seasonal_items(item_id,season_name,available_from,available_until,is_active)
select ci.id,'원정 명품관 명예 테두리 2차',
       '2026-11-04 00:00:00+09'::timestamptz,
       '2026-11-10 00:00:00+09'::timestamptz,true
from public.cosmetic_items ci
where ci.item_uid in ('PRESTIGE_PEARL_2026','PRESTIGE_DARKFLAME_2026','PRESTIGE_FROST_2026')
on conflict(item_id) do update
set season_name=excluded.season_name,available_from=excluded.available_from,
    available_until=excluded.available_until,is_active=true;

insert into public.expedition_luxury_catalog
  (cosmetic_item_id,luxury_group,required_effect_level,presentation_kind,is_active,metadata)
select ci.id,'B',2,'PRESTIGE_BORDER_IMAGE',true,
       '{"trial_open":false}'::jsonb
from public.cosmetic_items ci
where ci.item_uid in ('PRESTIGE_PEARL_2026','PRESTIGE_DARKFLAME_2026','PRESTIGE_FROST_2026')
on conflict(cosmetic_item_id) do update
set luxury_group=excluded.luxury_group,
    required_effect_level=excluded.required_effect_level,
    presentation_kind=excluded.presentation_kind,is_active=true,
    metadata=excluded.metadata;

commit;

-- 확인용: 3줄이 나오고 required_effect_level=2, trial_open=false, price=300 이어야 합니다.
select ci.item_uid, ci.name, lc.luxury_group, lc.required_effect_level,
       lc.metadata->>'trial_open' as trial_open,
       cp.price, si.available_from, si.available_until
from public.cosmetic_items ci
join public.expedition_luxury_catalog lc on lc.cosmetic_item_id=ci.id
join public.seasonal_items si on si.item_id=ci.id
left join public.cosmetic_item_pricings cp on cp.item_id=ci.id and cp.is_active=true
where ci.item_uid in ('PRESTIGE_PEARL_2026','PRESTIGE_DARKFLAME_2026','PRESTIGE_FROST_2026')
order by ci.item_uid;
